UPDATE ai_model_icon
SET icon_name = #{iconName,jdbcType=VARCHAR},
    icon_url = #{iconUrl,jdbcType=VARCHAR},
    object_key = #{objectKey,jdbcType=VARCHAR},
    description = #{description,jdbcType=VARCHAR}
WHERE id = #{id,jdbcType=BIGINT}

